changeSet.sql:
SET LOCAL lock_timeout = '5s';
LOCK TABLE nexus.taxonomy_centroids_384, nexus.taxonomy_centroids_768, nexus.taxonomy_centroids_1024 IN ACCESS EXCLUSIVE MODE;
ALTER TABLE nexus.taxonomy_centroids_384  NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.taxonomy_centroids_768  NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.taxonomy_centroids_1024 NO FORCE ROW LEVEL SECURITY;

INSERT INTO nexus.taxonomy_centroids (tenant_id, collection, topic_id, embedding_384, label, doc_count, created_at)
SELECT tenant_id, collection, topic_id, embedding, label, doc_count, created_at
FROM nexus.taxonomy_centroids_384;

INSERT INTO nexus.taxonomy_centroids (tenant_id, collection, topic_id, embedding_768, label, doc_count, created_at)
SELECT tenant_id, collection, topic_id, embedding, label, doc_count, created_at
FROM nexus.taxonomy_centroids_768;

INSERT INTO nexus.taxonomy_centroids (tenant_id, collection, topic_id, embedding_1024, label, doc_count, created_at)
SELECT tenant_id, collection, topic_id, embedding, label, doc_count, created_at
FROM nexus.taxonomy_centroids_1024;

ALTER TABLE nexus.taxonomy_centroids ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.taxonomy_centroids FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.taxonomy_centroids
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

CREATE INDEX idx_taxonomy_centroids_embedding_384
    ON nexus.taxonomy_centroids USING hnsw (embedding_384 vector_cosine_ops)
    WITH (m = 16, ef_construction = 64);
CREATE INDEX idx_taxonomy_centroids_embedding_768
    ON nexus.taxonomy_centroids USING hnsw (embedding_768 vector_cosine_ops)
    WITH (m = 16, ef_construction = 64);
CREATE INDEX idx_taxonomy_centroids_embedding_1024
    ON nexus.taxonomy_centroids USING hnsw (embedding_1024 vector_cosine_ops)
    WITH (m = 16, ef_construction = 64);

